function loadedSignals = trimIncompleteWindows(loadedSignals, ratio)
% Trim the last incomplete window of each signal in loadedSignals.
%
% INPUT:
%   loadedSignals  - struct generated by loadSignalsFromMat()
%   ratio          - threshold for trimming the last window
%                    Example: 0.5 = trim only if remainder < 50% of window
%
% OUTPUT:
%   loadedSignals  - struct with trimmed .data, .artif, .artifBin,
%                    and .artifMulti if sizes allow

    if nargin < 2
        ratio = 0.5;   % default: trim if < half-window
    end

    sigNames = fieldnames(loadedSignals);

    fprintf("\n--- Trimming incomplete windows (ratio=%.2f) ---\n", ratio);

    for i = 1:numel(sigNames)
        name = sigNames{i};
        sig = loadedSignals.(name);

        % required fields
        if ~isfield(sig, "data") || ~isfield(sig, "samplingFreq")
            continue;
        end

        fs = sig.samplingFreq;
        samplesPerWin = double(round(fs));             % 1-second window
        totalSamples = double(size(sig.data, 2));

        fullWindows = floor(totalSamples / samplesPerWin);
        keepSamples = fullWindows * samplesPerWin;
        remainder = totalSamples - keepSamples;

        if remainder == 0
            % Perfect division → nothing to trim
            continue;
        end

        % decide to trim
        if remainder < ratio * samplesPerWin
            loadedSignals.(name).data = sig.data(:, 1:keepSamples);

            if isfield(sig, "artif")
                loadedSignals.(name).artif = sig.artif(:, 1:fullWindows);
            end
            if isfield(sig, "artifBin")
                loadedSignals.(name).artifBin = sig.artifBin(1:fullWindows);
            end
            if isfield(sig, "artifMulti")
                loadedSignals.(name).artifMulti = sig.artifMulti(:, 1:fullWindows);
            end

            fprintf("Trimmed %s  (%d → %d samples)\n", ...
                name, totalSamples, keepSamples);
        end
    end
end
